// Human-screen payload only. Never use this output as a spoken customer message.
function value(name) {
  var x = Context.getVariable(name);
  return x === null || x === undefined ? '' : String(x).trim();
}
function safe(s) {
  return String(s).replace(/\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b/gi, '')
    .replace(/\s+/g, ' ').trim();
}
function readable(s) {
  return s && !/available|on[- ]file|unknown|not provided|undefined|null|<|>/i.test(s);
}
function section(text, label) {
  var match = text.match(new RegExp('(?:^|\\|\\|)\\s*' + label + ':\\s*([\\s\\S]*?)(?=\\|\\||$)', 'i'));
  return match ? safe(match[1]) : '';
}
// Clear first, so a stale payload from an earlier attempt can never look ready.
var suppliedSummary = value('Interaction summary');
var suppliedReason = value('Transfer reason');
Context.setVariable('Transfer Data', '');
var verified = value('authenticated').toLowerCase() === 'true';
var parts = [];
if (verified) {
  var name = [value('customer_fname'), value('customer_lname')].filter(readable).map(safe).join(' ');
  var memberNo = safe(value('member_number'));
  parts.push('CUSTOMER: ' + (name || 'Name not returned') + (memberNo ? ' (' + memberNo + ')' : '') + ' | Membership verified (SMS code)');
  var contact = [];
  var phone = value('phone_number').replace(/[\s().-]/g, '');
  var email = value('customer_email');
  if (/^\+?\d{10,15}$/.test(phone)) contact.push(phone);
  if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) contact.push(email);
  if (contact.length) parts.push('CONTACT: ' + contact.join(' | '));
} else {
  parts.push('CUSTOMER: Unverified caller | Verify membership before discussing reservations');
}
var issue = section(suppliedSummary, 'ISSUE') ||
  safe(suppliedSummary.replace(/(?:^|\|\|)\s*ACTIONS:[\s\S]*?(?=\|\||$)/i, '').replace(/^\s*\|\|/, '')
    .replace(/^INTERACTION SUMMARY:\s*/i, ''));
if (issue) parts.push('ISSUE: ' + issue);
var actions = section(suppliedSummary, 'ACTIONS');
if (actions && !/^none\.?$/i.test(actions)) parts.push('COMPLETED: ' + actions);
var team = section(suppliedReason, 'TEAM');
if (team) parts.push('TEAM: ' + team);
var next = section(suppliedReason, 'NEXT ACTION') ||
  safe(suppliedReason.replace(/(?:^|\|\|)\s*TEAM:[\s\S]*?(?=\|\||$)/i, '').replace(/^\s*\|\|/, '')
    .replace(/^(TRANSFER REASON|NEXT ACTION):\s*/i, ''));
// Keep the golden export contract: summary + reason -> Transfer Data.
if (issue && next) {
  var summary = parts.join(' || ');
  Context.setVariable('Interaction summary', summary);
  Context.setVariable('Transfer reason', 'NEXT ACTION: ' + next);
  Context.setVariable('Transfer Data', summary + ' || NEXT ACTION: ' + next);
}

// Read the member's phone from context (set by verify_otp) - not a model input
var smsDigits = String(Context.getVariable("phone_number") || "").replace(/\D/g, "");
Context.setVariable("SMS_Number", smsDigits ? "+" + smsDigits : "");
Context.setVariable("SMS_Message", String(Context.getVariable("sms_message") || ""));

// "true" for +1 numbers (US/Canada) -> US sender; anything else -> UK sender
Context.setVariable("wf_sms_from_us_number", (smsDigits.length === 11 && smsDigits.charAt(0) === "1") ? "true" : "false");

// Read the member's phone from context (set by verify_otp) - not a model input
var smsDigits = String(Context.getVariable("phone_number") || "").replace(/\D/g, "");
Context.setVariable("SMS_Number", smsDigits ? "+" + smsDigits : "");
Context.setVariable("SMS_Message", String(Context.getVariable("sms_message") || ""));

// "true" for +1 numbers (US/Canada) -> US sender; anything else -> UK sender
Context.setVariable("wf_sms_from_us_number", (smsDigits.length === 11 && smsDigits.charAt(0) === "1") ? "true" : "false");

// Read the member's phone from context (set by verify_otp) - not a model input
var smsDigits = String(Context.getVariable("phone_number") || "").replace(/\D/g, "");
Context.setVariable("SMS_Number", smsDigits ? "+" + smsDigits : "");
Context.setVariable("SMS_Message", String(Context.getVariable("sms_message") || ""));

// "true" for +1 numbers (US/Canada) -> US sender; anything else -> UK sender
Context.setVariable("wf_sms_from_us_number", (smsDigits.length === 11 && smsDigits.charAt(0) === "1") ? "true" : "false");

// random number between 100000 and 999999 to avoid leading zeros
let oneTimePin = String(Math.floor(Math.random() * 900000) + 100000);

Context.setVariable('One_Time_Pin', oneTimePin);

Context.setVariable('SMS_Number', '+' +
    Context.getVariable('phone_number').replace(/\D/g, ""));

Context.setVariable('SMS_Message',
    'Your one-time authentication PIN is ' + oneTimePin);

// Stage the looked-up member; only verify_otp promotes these on a matching code
Context.setVariable("wf_pending_member_id", String(Context.getVariable("pending_member_id") || ""));
Context.setVariable("wf_pending_member_number", String(Context.getVariable("pending_member_number") || ""));
Context.setVariable("wf_pending_fname", String(Context.getVariable("pending_customer_fname") || ""));
Context.setVariable("wf_pending_lname", String(Context.getVariable("pending_customer_lname") || ""));
Context.setVariable("wf_pending_email", String(Context.getVariable("pending_customer_email") || ""));
Context.setVariable("wf_pending_phone", '+' + String(Context.getVariable('phone_number') || "").replace(/\D/g, ""));

// "true" for +1 numbers (US/Canada) -> US sender; anything else -> UK sender
var smsDigits = String(Context.getVariable('phone_number') || "").replace(/\D/g, "");
Context.setVariable("wf_sms_from_us_number", (smsDigits.length === 11 && smsDigits.charAt(0) === "1") ? "true" : "false");

var MAX_ATTEMPTS = 3;
var wf_entered_pin = String(Context.getVariable("entered_pin") || "").replace(/\D/g, "");
var wf_sent_pin = String(Context.getVariable("sent_pin") || "").replace(/\D/g, "");
var wf_pending_id = String(Context.getVariable("pending_member_id") || "");
var wf_attempts = parseInt(String(Context.getVariable("otp_attempts") || "0"), 10) || 0;

if (wf_attempts >= MAX_ATTEMPTS) {
    // Already locked out: never authenticate, even with the right code.
    Context.setVariable("wf_otp_result", "LOCKED");
    Context.setVariable("wf_authenticated", "false");
} else if (wf_sent_pin.length === 6 && wf_entered_pin === wf_sent_pin && wf_pending_id !== "") {
    Context.setVariable("wf_otp_result", "MATCH");
    Context.setVariable("wf_authenticated", "true");
    Context.setVariable("wf_member_id", wf_pending_id);
    Context.setVariable("wf_member_number", String(Context.getVariable("pending_member_number") || ""));
    Context.setVariable("wf_customer_fname", String(Context.getVariable("pending_customer_fname") || ""));
    Context.setVariable("wf_customer_lname", String(Context.getVariable("pending_customer_lname") || ""));
    Context.setVariable("wf_customer_email", String(Context.getVariable("pending_customer_email") || ""));
    Context.setVariable("wf_phone_number", String(Context.getVariable("pending_phone_number") || ""));
} else {
    wf_attempts = wf_attempts + 1;
    Context.setVariable("wf_otp_result", wf_attempts >= MAX_ATTEMPTS ? "LOCKED" : "NO_MATCH");
    Context.setVariable("wf_authenticated", "false");
}
Context.setVariable("wf_otp_attempts", String(wf_attempts));

var wf_result = String(Context.getVariable("wf_otp_result") || "");
var wf_next;
if (wf_result === "MATCH") {
    wf_next = "Verified. Do not call verify_otp again. Your next action is execute_sql to log auth_success (step f), then return {\"auth_result\": \"success\"}.";
} else if (wf_result === "LOCKED") {
    wf_next = "Locked out. Do not call verify_otp or send_one_time_pin again. Your next action is execute_sql to log the failure (step h), then return {\"auth_result\": \"failed\", \"failure_reason\": \"max_attempts\"}.";
} else if (wf_attempts <= 1) {
    wf_next = "Wrong code. Do not call verify_otp again in this turn. Your next action is reply_to_coordinator with exactly: STATUS: NEED_INPUT | ASK_CUSTOMER: \"That code didn't match. What is the 6-digit code you received? If you'd like, I can send you a new one.\"";
} else {
    wf_next = "Wrong code again. Do not call verify_otp again in this turn. Your next action is reply_to_coordinator with exactly: STATUS: NEED_INPUT | ASK_CUSTOMER: \"That code still didn't match, and you have one try left. Please check the text message and enter the 6-digit code, or I can send you a new one.\"";
}
Context.setVariable("wf_otp_next_step", wf_next);
